"kind": "propose",
"summary": "Liveness probe timeout is too short for the application's startup time",
"hypotheses": [
  {
    "root_cause_class": "probe_too_strict_for_startup",
    "summary": "Liveness probe timeout (1s) is shorter than the app's 32s startup time",
    "supporting": ["probe_kills", "killed_during_startup", "ev-rollout_history", "ev-container_logs_tail"],
    "contradicting": ["probe_timeouts"],
    "missing": [],
    "status": "supported"
  },
  {
    "root_cause_class": "insufficient_evidence",
    "summary": "Logs confirm app is functional during probe failures",
    "supporting": ["ev-container_logs_tail"],
    "contradicting": [],
    "missing": [],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-probes",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "finance",
    "name": "ledger",
    "uid": "uid-deployment-ledger"
  },
  "params": {
    "container": "app",
    "liveness": {
      "timeoutSeconds": 10
    }
  },
  "expected_effect": "Allow 10s for app to start before liveness probe times out",
  "rationale": "The app ran 32s before being killed, but liveness probe timeout is 1s. Increasing timeout to 10s matches the startup duration, preventing premature kills.",
  "cited_evidence_ids": ["ev-rollout_history", "ev-pod_states", "ev-target_events", "ev-container_logs_tail"],
  "cited_predicates": ["killed_during_startup", "probe_kills"]
}
}
